package rs.unicredit.cbr.service;

import java.io.StringReader;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.OffsetDateTime;
import java.util.Iterator;
import java.util.UUID;

import javax.xml.namespace.NamespaceContext;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpressionException;
import javax.xml.xpath.XPathFactory;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.model.MessageType;
import rs.unicredit.cbr.model.ParseStatus;
import rs.unicredit.cbr.model.TransferDirection;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;

/**
 * Minimal pacs.008 parser to populate TBL_CBR_TRANSACTION from a raw XML request.
 * Intended as a lightweight bridge until full MQ ingestion is wired.
 */
@Service
@RequiredArgsConstructor
public class Pacs008ParserService {

    private static final Logger LOG = LoggerFactory.getLogger(Pacs008ParserService.class);

    private static final String NS_MAIN = "urn:iso:std:iso:20022:tech:xsd:pacs.008.001.08.OM.001";
    private static final String NS_ISO = "urn:iso:std:iso:20022:tech:xsd:pacs.008.001.08";

    private final CbrTransactionRepository transactionRepository;
    private final CbrTransactionRequestRepository requestRepository;

    @Transactional
    public CbrTransaction parseAndSave(CbrTransactionRequest request) {
        try {
            Document doc = buildDocument(request.getRawXml());
            XPath xpath = buildXPath();

            String msgId = text(xpath, doc, "/urn:Document/urn:FIToFICstmrCdtTrf/urn:GrpHdr/iso:MsgId");
            String creDtTm = text(xpath, doc, "/urn:Document/urn:FIToFICstmrCdtTrf/urn:GrpHdr/iso:CreDtTm");
            String txId = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/urn:PmtId/iso:TxId");
            String endToEndId = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/urn:PmtId/iso:EndToEndId");
            String amountStr = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:IntrBkSttlmAmt");
            String currency = attr(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:IntrBkSttlmAmt/@Ccy");
            String settlementDateStr = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:IntrBkSttlmDt");
            String paymentServiceLevel = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:GrpHdr/iso:SttlmInf/iso:ClrSys/iso:Prtry");

            String debtorName = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:Dbtr/iso:Nm");
            String debtorIban = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:DbtrAcct/iso:Id/iso:IBAN");
            String creditorName = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:Cdtr/iso:Nm");
            String creditorIban = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:CdtrAcct/iso:Id/iso:IBAN");
            String remittanceInfo = text(xpath, doc,
                    "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:RmtInf/iso:Ustrd");

            LocalDateTime sourceReceivedAt = parseDateTimeOrNow(creDtTm);
            LocalDate settlementDate = parseDateOrToday(settlementDateStr);
            BigDecimal settlementAmount = parseAmount(amountStr);
            String settlementCurrency = notBlank(currency) ? currency : "XXX";

            String callReplyRef = firstNonBlank(txId, msgId, endToEndId, UUID.randomUUID().toString());
            String paymentReference = firstNonBlank(txId, endToEndId, msgId, callReplyRef);
            String paymentService = notBlank(paymentServiceLevel) ? paymentServiceLevel : "UNKNOWN";

            CbrTransaction txn = new CbrTransaction();
            txn.setRequest(request);
            txn.setCallReplyRef(callReplyRef);
            txn.setMessageType(MessageType.P8);
            txn.setDirection(TransferDirection.IN); // adjust if you can infer direction
            txn.setPaymentReference(paymentReference);
            txn.setSourceReceivedAt(sourceReceivedAt);
            txn.setSettlementAmount(settlementAmount);
            txn.setSettlementCurrency(settlementCurrency);
            txn.setSettlementDate(settlementDate);
            txn.setPaymentServiceLevel(paymentService);
            txn.setPaymentLocalInstrument(paymentServiceLevel);
            txn.setDebtorName(debtorName);
            txn.setDebtorIban(debtorIban);
            txn.setCreditorName(creditorName);
            txn.setCreditorIban(creditorIban);
            txn.setRemittanceInfo(remittanceInfo);

            CbrTransaction saved = transactionRepository.save(txn);

            request.setParseStatus(ParseStatus.PARSED);
            request.setErrorMessage(null);
            requestRepository.save(request);

            LOG.info("Parsed pacs.008 request id={} into transaction id={} (TxId={}, MsgId={})",
                    request.getId(), saved.getId(), txId, msgId);
            return saved;
        } catch (Exception e) {
            request.setParseStatus(ParseStatus.FAILED);
            request.setErrorMessage(e.getMessage());
            requestRepository.save(request);
            LOG.error("Failed to parse pacs.008 request id={}", request.getId(), e);
            throw new IllegalStateException("Failed to parse pacs.008", e);
        }
    }

    private Document buildDocument(String xml) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        try (StringReader reader = new StringReader(xml)) {
            return factory.newDocumentBuilder().parse(new InputSource(reader));
        }
    }

    private XPath buildXPath() {
        XPath xpath = XPathFactory.newInstance().newXPath();
        xpath.setNamespaceContext(new NamespaceContext() {
            @Override
            public String getNamespaceURI(String prefix) {
                if ("urn".equals(prefix)) {
                    return NS_MAIN;
                }
                if ("iso".equals(prefix)) {
                    return NS_ISO;
                }
                return null;
            }

            @Override
            public String getPrefix(String namespaceURI) {
                if (NS_MAIN.equals(namespaceURI)) {
                    return "urn";
                }
                if (NS_ISO.equals(namespaceURI)) {
                    return "iso";
                }
                return null;
            }

            @Override
            public Iterator<String> getPrefixes(String namespaceURI) {
                return null;
            }
        });
        return xpath;
    }

    private String text(XPath xpath, Document doc, String expr) throws XPathExpressionException {
        String value = (String) xpath.evaluate(expr, doc, XPathConstants.STRING);
        return notBlank(value) ? value.trim() : null;
    }

    private String attr(XPath xpath, Document doc, String expr) throws XPathExpressionException {
        String value = (String) xpath.evaluate(expr, doc, XPathConstants.STRING);
        return notBlank(value) ? value.trim() : null;
    }

    private boolean notBlank(String value) {
        return value != null && !value.trim().isEmpty();
    }

    private String firstNonBlank(String... values) {
        for (String v : values) {
            if (notBlank(v)) {
                return v;
            }
        }
        return null;
    }

    private BigDecimal parseAmount(String value) {
        try {
            return notBlank(value) ? new BigDecimal(value.trim()) : BigDecimal.ZERO;
        } catch (Exception e) {
            return BigDecimal.ZERO;
        }
    }

    private LocalDate parseDateOrToday(String value) {
        try {
            return notBlank(value) ? LocalDate.parse(value.trim()) : LocalDate.now();
        } catch (Exception e) {
            return LocalDate.now();
        }
    }

    private LocalDateTime parseDateTimeOrNow(String value) {
        try {
            if (notBlank(value)) {
                return OffsetDateTime.parse(value.trim()).toLocalDateTime();
            }
        } catch (Exception ignored) {
            try {
                return LocalDateTime.parse(value.trim());
            } catch (Exception ignored2) {
                // fall through
            }
        }
        return LocalDateTime.now();
    }
}

