-- Schema for CBR request (call) handling, based on [RS] OM/GSE integration with local CBR spec.
-- Napomene:
-- - TBL_CBR_TRANSACTION referencira ID iz TBL_CBR_TRANSACTION_REQUEST (REQUEST_ID).
-- - CALL_REPLY_REF ostaje jedinstven za korelaciju, ali primarni kljuc je ID.
-- - Agent kolone bez sufiksa _BIC; ID razdvojeni (BIC/LEI/OTHR/PRVTID).
-- - Address country/text izbaceni; postal address dodate.
-- - DR/CR statistical code u glavnoj tabeli; child stat bez event datuma/drzave.
-- - Request tabela sadrzi samo sirovi XML + status/izvor.

CREATE SEQUENCE TBL_CBR_TRANSACTION_SEQ START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE TBL_CBR_TRANSACTION_REQUEST_SEQ START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE TBL_CBR_TRANSACTION_STAT_SEQ START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;


CREATE TABLE TBL_CBR_TRANSACTION_REQUEST (
    ID NUMBER(19) NOT NULL,
    SOURCE_SYSTEM VARCHAR2(20 CHAR),
    RECEIVED_AT TIMESTAMP(6) DEFAULT SYSTIMESTAMP,
    RAW_XML CLOB NOT NULL,
    PARSE_STATUS VARCHAR2(20 CHAR) DEFAULT 'RECEIVED',
    ERROR_MESSAGE VARCHAR2(1024 CHAR),
    CONSTRAINT PK_TBL_CBR_TRANSACTION_REQUEST PRIMARY KEY (ID)
);

CREATE TABLE TBL_CBR_TRANSACTION (
    ID NUMBER(19) NOT NULL,
    REQUEST_ID NUMBER(19) NOT NULL,
    CALL_REPLY_REF VARCHAR2(70 CHAR) NOT NULL,
    MESSAGE_TYPE VARCHAR2(10 CHAR) NOT NULL,
